import * as fs from 'node:fs';
import * as path from 'node:path';

import { getTaskConfigDir } from './configDir.js';
import { describeError } from './describeError.js';
import { registerInitializedProject } from './registerInitializedProject.js';

const PROJECT_CONFIG_TEMPLATE = `# Task configuration for this project
# Generated by: task init

statuses:
  - backlog
  - in-progress
  - name: done
    terminal: true

# fields:
#   - name: component
#     type: string
#     required: false

# defaults:
#   priority: medium

# hooks:
#   onTaskCreated: ""
#   onStatusChange: ""
`;

/** How registering the initialized project went; a registry failure does not undo the initialization. */
export type InitRegistration = { ok: true; added: boolean } | { ok: false; message: string; hint?: string };

export interface InitProjectResult {
	/** `<dir>/.task`. */
	taskDir: string;
	/** False when `.task` already existed: nothing was written to it. */
	created: boolean;
	registration: InitRegistration;
}

/**
 * `task init`: creates `<dir>/.task/tasks` and `config.yml` (from the template), creating `dir` and its parents when
 * missing, then registers the project for the app-module. Idempotent: an existing `.task` is left untouched and the
 * project is registered all the same (how a project initialized before the registry existed gets registered).
 * Never fails on the registry: the project is initialized either way, so the failure comes back in `registration`.
 * The directory is not validated here (see `addProject` for the checks of the UI).
 */
export function initProject(dir: string, configDir: string = getTaskConfigDir()): InitProjectResult {
	const taskDir = path.join(dir, '.task');
	const created = !fs.existsSync(taskDir);
	if (created) {
		fs.mkdirSync(path.join(taskDir, 'tasks'), { recursive: true });
		fs.writeFileSync(path.join(taskDir, 'config.yml'), PROJECT_CONFIG_TEMPLATE, 'utf8');
	}
	try {
		const { added } = registerInitializedProject(configDir, dir);
		return { taskDir, created, registration: { ok: true, added } };
	} catch (error) {
		const { message, hint } = describeError(error);
		return { taskDir, created, registration: { ok: false, message, ...(hint === undefined ? {} : { hint }) } };
	}
}
